def count_mod_3():
    # a3 must be non-zero mod 3: a3 in {1, 2}
    # a1 in {0, 1, 2}
    count = 0
    for a3 in [1, 2]:
        for a1 in range(3):
            if (a3 + a1) % 3 != 0:
                count += 1
    print(f"N_3: {count}")

def count_mod_11():
    # a3 and a1 must be non-zero mod 11: a3, a1 in {1, ..., 10}
    # Constraint: c = a1*a3^-1 != 0 mod 11. Since a3, a1 are non-zero, this is always true.
    count = 10 * 10
    print(f"N_11: {count}")

